def shortest_path(graph, source, target):
    length = [[float('inf') for x in range(len(graph) + 1)]][0]
    path = [[None for x in range(len(graph) + 1)]][0]
    queue = [[0, source]]
    while queue:
        cost, current = queue.pop(0)
        if current == target:
            path = []
            while current is not None:
                path.append(current)
                current = path[-2]
            return (cost, path[::-1])
        for neighbor, weight in graph.get(current, []):
            if cost + weight < length[neighbor]:
                length[neighbor] = cost + weight
                path[neighbor] = current
                queue.append([cost + weight, neighbor])
    return (float('inf'), None)
